import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

/**
 * bbox-ui EditableText layout — the portable geometry of the text-leaf.
 *
 * EditableText's own size ladder, deliberately NOT `layout.ts`'s `TEXT_SIZES`
 * (frozen for T1) and NOT `Glyph`'s or `Port`'s own independent ladders —
 * see docs/T1-SPEC.md §0 on why three components each get their own 18px
 * "small" rung rather than one shared file. React-free, engine-free, same
 * discipline as `layout.ts`.
 *
 * PROVENANCE: OURS, AD HOC. NO PRIOR ART IS CLAIMED, and this file has no
 * donor — stated explicitly rather than left as an absence, because an
 * uncited file is ambiguous between "written here" and "nobody wrote down
 * where this came from", and only one of those is true.
 *
 * There is also no algorithm here to have prior art FOR. Every export is a
 * lookup table or a total `Record` over a string union: the size ladder, the
 * three font stacks, and the two align→flex maps. The one function with a
 * rule in it, `editableTextFontPx`, is a single ternary. The CSS values on
 * the right-hand side of those Records (`flex-start`/`center`/`flex-end`)
 * are of course the CSS Flexbox spec's, but this file does not implement
 * them — it names them and hands them to the browser, which is not a
 * citation-bearing act. The reason the tables are TOTAL Records rather than
 * ternaries is a real decision and it is documented at each seam below.
 */

/** EditableText's own ladder. Values match the board's own Text Size row. */
export const EDITABLE_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
// WHY `EditableTextSize` widens by union rather than `EDITABLE_TEXT_SIZES` growing a
// fifth rung: "custom" has no single px value — it is the ESCAPE from the
// named ladder into `sizePx`, so it cannot live in a `Record<name, px>` the
// way sm/md/lg/xl do. `editableTextFontPx` below is the one place that resolves
// either shape back to a number. See docs/TEXTBOX-EDITING-SPEC.md §1.
export type EditableTextSize = keyof typeof EDITABLE_TEXT_SIZES | "custom";

/** The font-size in px for a given `size`/`sizePx` pair — the one function
 * that knows "custom" escapes the named ladder. `sizePx` is ignored for the
 * four named rungs, exactly like `font`/`align` ignore props that don't
 * apply to them. */
export function editableTextFontPx(size: EditableTextSize, sizePx: number): number {
  return size === "custom" ? sizePx : EDITABLE_TEXT_SIZES[size];
}

// WHY the array is the source and the type is derived: annotating the field
// table stopped the SCHEMA advertising a value the component cannot render,
// but not the reverse — widening the union and adding its stack left the
// panel silently offering three of four fonts with the suite green. With one
// runtime array behind both, a test can pin the field's options to it and
// catch growth in either direction. Same shape as BLOCK_ORIENTATIONS.
export const EDITABLE_TEXT_FONTS = ["sans", "sketch", "mono"] as const;
export type EditableTextFont = (typeof EDITABLE_TEXT_FONTS)[number];
export const EDITABLE_TEXT_FONT_STACKS: Record<EditableTextFont, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
  sketch: '"Segoe Print", "Bradley Hand", cursive',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
};

type FlexPlacement = "flex-start" | "center" | "flex-end";

// WHY total Records rather than the ternaries these replace: deriving the
// union from the array made widening it reach the panel automatically, which
// is what we wanted — but a ternary has a fall-through, so a new member
// arrived as a live segment that silently rendered `center`, typecheck clean
// and every test green. A total Record is what makes the array the real
// source: adding a member is a compile error until someone says where it
// lays out. The same shape as EDITABLE_TEXT_FONT_STACKS, which is why `font`
// already failed loudly and these two did not.
export const EDITABLE_TEXT_VERTICAL_ALIGNS = ["top", "middle", "bottom"] as const;
export type EditableTextVerticalAlign = (typeof EDITABLE_TEXT_VERTICAL_ALIGNS)[number];
export const EDITABLE_TEXT_ALIGN_ITEMS: Record<EditableTextVerticalAlign, FlexPlacement> = {
  top: "flex-start",
  middle: "center",
  bottom: "flex-end",
};
export function editableTextAlignItems(align: EditableTextVerticalAlign): FlexPlacement {
  return EDITABLE_TEXT_ALIGN_ITEMS[align];
}

export const EDITABLE_TEXT_HORIZONTAL_ALIGNS = ["left", "middle", "right"] as const;
export type EditableTextHorizontalAlign = (typeof EDITABLE_TEXT_HORIZONTAL_ALIGNS)[number];
export const EDITABLE_TEXT_JUSTIFY_CONTENT: Record<EditableTextHorizontalAlign, FlexPlacement> = {
  left: "flex-start",
  middle: "center",
  right: "flex-end",
};
export function editableTextJustifyContent(justify: EditableTextHorizontalAlign): FlexPlacement {
  return EDITABLE_TEXT_JUSTIFY_CONTENT[justify];
}

/**
 * src/components/glyph.layout.ts — ported by value from
 * packages/bbox-ui/src/glyph.layout.ts (Glyph v2, docs/GLYPH-PLAN.md's
 * contract). Same size ladder and override-vs-preset rule; this app has no
 * `layout.ts`/`TEXT_SIZES` of its own to stay independent of, but the
 * ladder is kept in its own file anyway so `glyph.tsx` matches its source
 * shape 1:1 for anyone diffing the two later.
 *
 * DONOR LINES (read 2026-09-17; the donor is 53 lines and lives in this
 * same repo, so this is a `diff` away, not an archaeology dig):
 *   • `glyph.layout.ts:11`    `GLYPH_SIZES` — same four rungs, same values.
 *   • `glyph.layout.ts:20-43` the two interfaces.
 *   • `glyph.layout.ts:45-52` `glyphFootprint`, including the `!== undefined`
 *     rule restated below. Arithmetic unchanged.
 *
 * NO PRIOR ART IS CLAIMED, and none applies: the "ladder plus override"
 * rule and the square `size + 2*padding` footprint are this repo's own
 * product decisions, not an algorithm. There is nothing here to cite but
 * the donor.
 */
export const GLYPH_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type GlyphSize = keyof typeof GLYPH_SIZES;
export const GLYPH_SIZE_NAMES: Record<GlyphSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

export interface GlyphFootprintInput {
  sizePreset?: GlyphSize;
  /** px override — when given, wins over `sizePreset`. */
  size?: number;
  padding?: number;
}

export interface GlyphFootprint {
  /** Resolved side length of the glyph itself, px. */
  size: number;
  padding: number;
  /** Outer box a host places on canvas — `size + 2*padding`, square. */
  w: number;
  h: number;
}

/**
 * The override-vs-preset size rule, in one place. `size` absent/undefined
 * is NOT the same as `size: 0` — an explicit 0 is a real override, so this
 * checks `!== undefined`, never falsy/`??`, to keep that case distinguishable.
 */
export function glyphFootprint({
  sizePreset = "sm",
  size,
  padding = 0,
}: GlyphFootprintInput): GlyphFootprint {
  const resolvedSize = size !== undefined ? size : GLYPH_SIZES[sizePreset];
  const outer = resolvedSize + 2 * padding;
  return { size: resolvedSize, padding, w: outer, h: outer };
}

// src/components/toggle-group.tsx — port of
// packages/inspector/src/components/ui/toggle-group.tsx (already Base UI,
// already carries the `spacing` prop this design wants — see
// docs/menus/MENU-KIT-DESIGN.md §3.1), `cn` repointed to this app's own
// `../lib/utils` and `toggleVariants` repointed to this app's own
// `./toggle` (the trunk's already-migrated Toggle, not the donor's sibling
// copy).
"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group";
import { type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { toggleVariants } from "./toggle";

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
    orientation?: "horizontal" | "vertical";
  }
>({
  size: "default",
  variant: "default",
  spacing: 2,
  orientation: "horizontal",
});

function ToggleGroup({
  className,
  variant,
  size,
  spacing = 2,
  orientation = "horizontal",
  children,
  ...props
}: ToggleGroupPrimitive.Props &
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
    orientation?: "horizontal" | "vertical";
  }) {
  return (
    <ToggleGroupPrimitive
      data-slot="toggle-group"
      data-variant={variant}
      data-size={size}
      data-spacing={spacing}
      data-orientation={orientation}
      style={{ "--gap": spacing } as React.CSSProperties}
      // WHY `data-[orientation=vertical]:` rather than the donor's bare
      // `data-vertical:` (same measured bug as button-group.tsx's
      // `ButtonGroupSeparator` and this app's own separator.tsx): Base UI's
      // `ToggleGroup` sets a single `data-orientation="horizontal"|"vertical"`
      // attribute (`ToggleGroupDataAttributes.js`), never a bare
      // `data-horizontal`/`data-vertical` presence attribute — `data-vertical:`
      // lowers to `[data-vertical]`, which this DOM never has, so the donor's
      // vertical-orientation styling was dead CSS.
      className={cn(
        "isolate group/toggle-group flex w-fit flex-row items-center gap-[--spacing(var(--gap))] rounded-lg data-[size=sm]:rounded-[min(var(--radius-md),10px)] data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size, spacing, orientation }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  );
}

function ToggleGroupItem({
  className,
  children,
  variant = "default",
  size = "default",
  ...props
}: TogglePrimitive.Props & VariantProps<typeof toggleVariants>) {
  const context = React.useContext(ToggleGroupContext);

  return (
    <TogglePrimitive
      data-slot="toggle-group-item"
      data-variant={context.variant || variant}
      data-size={context.size || size}
      data-spacing={context.spacing}
      className={cn(
        "shrink-0 group-data-[spacing=0]/toggle-group:rounded-none group-data-[spacing=0]/toggle-group:px-2 focus:z-10 focus-visible:z-10 group-data-[spacing=0]/toggle-group:has-data-[icon=inline-end]:pr-1.5 group-data-[spacing=0]/toggle-group:has-data-[icon=inline-start]:pl-1.5 group-data-[orientation=horizontal]/toggle-group:data-[spacing=0]:first:rounded-l-lg group-data-[orientation=vertical]/toggle-group:data-[spacing=0]:first:rounded-t-lg group-data-[orientation=horizontal]/toggle-group:data-[spacing=0]:last:rounded-r-lg group-data-[orientation=vertical]/toggle-group:data-[spacing=0]:last:rounded-b-lg group-data-[orientation=horizontal]/toggle-group:data-[spacing=0]:data-[variant=outline]:border-l-0 group-data-[orientation=vertical]/toggle-group:data-[spacing=0]:data-[variant=outline]:border-t-0 group-data-[orientation=horizontal]/toggle-group:data-[spacing=0]:data-[variant=outline]:first:border-l group-data-[orientation=vertical]/toggle-group:data-[spacing=0]:data-[variant=outline]:first:border-t",
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        className,
      )}
      {...props}
    >
      {children}
    </TogglePrimitive>
  );
}

export { ToggleGroup, ToggleGroupItem };

// src/components/toggle.tsx — copied verbatim from
// packages/inspector/src/components/ui/toggle.tsx (the "blackbox toggle" —
// Zach's picked shadcn primitive, see CLAUDE.md's ai-comment thread: no
// label, no track-and-thumb, an icon-button with a pressed/unpressed
// visual state, which is exactly this shape). Only the `cn` import path
// changed — the source imports the `cn` npm package, this app has its own
// `src/lib/utils.ts`.
"use client";

import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_TOGGLE_SIZE, useBarSize } from "./barSize";

const toggleVariants = cva(
  "group/toggle inline-flex items-center justify-center gap-1 rounded-lg text-sm font-medium whitespace-nowrap transition-all outline-none hover:bg-muted hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 aria-pressed:bg-muted data-[state=on]:bg-muted dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border border-input bg-transparent hover:bg-muted",
      },
      size: {
        default:
          "h-8 min-w-8 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        sm: "h-7 min-w-7 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 min-w-9 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

// Same clamp Button's own CLAMPED_RADIUS_SIZES documents — `sm`'s
// `rounded-[min(var(--radius-md),12px)]` is a deliberate anti-balloon cap,
// not a plain `rounded-lg`, so the skin token does not reach it.
const CLAMPED_RADIUS_SIZES = new Set(["sm"]);

function Toggle({
  className,
  variant = "default",
  size,
  style,
  ...props
}: TogglePrimitive.Props & VariantProps<typeof toggleVariants>) {
  // Explicit `size` wins; the ambient Bar cascade (barSize.tsx) is only the
  // fallback when `size` itself is omitted, `"default"` (this component's
  // original default) is the floor when there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_TOGGLE_SIZE[barSize]) ?? "default";
  return (
    <TogglePrimitive
      data-slot="toggle"
      data-size={resolvedSize}
      className={cn(toggleVariants({ variant, size: resolvedSize, className }))}
      style={{
        // The skin seam (src/skin/skin.ts + skin.css) — see button.tsx's
        // identical note on why the clamped size is excluded.
        ...(CLAMPED_RADIUS_SIZES.has(resolvedSize ?? "default") ? null : { borderRadius: "var(--bbox-skin-radius, var(--radius-lg))" }),
        // `outline` is the one variant with a real border (`border-input`)
        // — `default` is `bg-transparent` with no border at all. Same
        // split Badge's own `outline` variant makes.
        ...(variant === "outline" ? { borderColor: "var(--bbox-skin-line-override, var(--color-input))" } : null),
        ...style,
      }}
      {...props}
    />
  );
}

export { Toggle, toggleVariants };

/**
 * src/editor/compareModel.ts — the three-state object diff behind the
 * Compare dialog's Properties table (docs/menus/screenshots/08).
 *
 * Ported from /home/bam/systemsketch/src/compare/compareModel.ts:47-496
 * with exactly one edit, per docs/menus/MENU-KIT-DESIGN.md ("with one edit:
 * BlockPort inlined as a four-field structural type, severing the last
 * tldraw-transitive type import"): the donor's
 * `import type { BlockPort } from '../blocks/blockModel'` (a `T.object(...)`
 * schema type built on tldraw's validation library, carrying ~20 SystemSketch
 * fields) is replaced by a local `PortLike` naming only the four fields this
 * file actually reads — `id` (identity, for the port map keys), and `name`/
 * `type`/`defaultValue` (`PORT_COMPARE_FIELDS`, below). Every other field on
 * the real `BlockPort` (`row`, `branch`, `commEdge`, `mutates`, `state`,
 * `link`, …) is irrelevant to a structural three-state diff and was never
 * read here — this is a narrowing to what the algorithm actually uses, not a
 * behavior change.
 *
 * Deliberately NOT ported: `recordsOfSnapshot` (donor :498-511). It pulls a
 * `RecordMap` out of a raw tldraw store snapshot — the tldraw *adapter's* job,
 * per docs/menus/MENU-KIT-DESIGN.md open decision #2 ("`recordsOfSnapshot`
 * does NOT come — it is the tldraw adapter"). This kit ships `compareBoards`
 * over the structural `RecordLike`/`RecordMap` types only; a host with a
 * different graph model supplies its own projection into those types and
 * never needs this function at all.
 */

/** The three states. Anything else is a presentation concern, not a state. */
export const CHANGE_KINDS = ["added", "removed", "modified"] as const
export type ChangeKind = (typeof CHANGE_KINDS)[number]

export const SUBJECT_KINDS = ["block", "port", "cable", "shape"] as const
export type SubjectKind = (typeof SUBJECT_KINDS)[number]

/** One field that exists on both sides with a different value. */
export interface FieldChange {
  readonly path: string
  readonly before: string
  readonly after: string
}

export interface CompareChange {
  /** Stable within one comparison; the table and the canvas both key on it. */
  readonly id: string
  readonly subject: SubjectKind
  readonly kind: ChangeKind
  /** What a person calls this thing. */
  readonly name: string
  /**
   * The element this change belongs to — a Block or a cable, NEVER a port.
   * A port's element is its host Block, so `run_predict.threshold` has
   * `element: 'run_predict'`. This is what the table groups by.
   */
  readonly element: string
  /** Stable id of that element, for grouping. */
  readonly elementId: string
  /** The change id of the Block this hangs under, for a nested table. */
  readonly parentId: string | null
  /** Where to draw on the before board. Null when the thing is not there. */
  readonly anchorBefore: string | null
  /** Where to draw on the after board. Null when the thing is not there. */
  readonly anchorAfter: string | null
  /** Set when the anchor is a port row rather than a whole shape. */
  readonly portId: string | null
  /**
   * Empty on `added` and `removed` — by construction, not by accident. A row
   * with no fields is a whole-object insertion or deletion.
   */
  readonly fields: readonly FieldChange[]
  /** The raw record this was computed from, for the Code tab. */
  readonly recordBefore: unknown | null
  readonly recordAfter: unknown | null
}

export interface SubjectTally {
  added: number
  removed: number
  modified: number
}

export interface BoardCompare {
  readonly changes: readonly CompareChange[]
  readonly tally: Readonly<Record<SubjectKind, SubjectTally>>
  readonly total: number
}

/**
 * Whether a row's Previous/Current cells may carry word-level ink.
 *
 * True only for `modified`, because only there do both a before and an after
 * value exist to align. This is the rule that keeps the table from inventing a
 * comparison, and it is the object-level counterpart of `wordDiff.changed`.
 */
export function canWordDiff(change: Pick<CompareChange, "kind" | "fields">): boolean {
  return change.kind === "modified" && change.fields.length > 0
}

// ---------------------------------------------------------------------------
// Reading the two snapshots
// ---------------------------------------------------------------------------

/** The shape of a record we care about, kept structural so tests need no store. */
export interface RecordLike {
  id: string
  typeName: string
  type?: string
  props?: Record<string, unknown>
  fromId?: string
  toId?: string
}

export type RecordMap = Readonly<Record<string, RecordLike>>

/**
 * The four `BlockPort` fields this diff actually reads. See the file header:
 * inlined structurally so this module needs no tldraw-transitive schema type.
 */
interface PortLike {
  readonly id: string
  readonly name: string
  readonly type: string
  readonly defaultValue?: string
}

/** A cable end, resolved from its binding record. */
interface CableEnd {
  shapeId: string
  portId: string
}

interface CableEnds {
  start: CableEnd | null
  end: CableEnd | null
}

/** Fields compared on a Block. Pose is deliberately absent — see below. */
export const BLOCK_COMPARE_FIELDS = ["title", "description", "blockType"] as const
/** Fields compared on a port row. */
export const PORT_COMPARE_FIELDS = ["name", "type", "defaultValue"] as const
/** Fields compared on a cable, beside its two endpoints. */
export const CABLE_COMPARE_FIELDS = ["temporal", "delayValue", "routing"] as const

/**
 * Position and z-order are appearance, not content.
 *
 * Every engineering tool in the prior-art sweep that has an opinion demotes or
 * hides pure positional change by default — LabVIEW behind a "Cosmetic"
 * checkbox, Camunda by only highlighting what "affects execution". A board
 * whose Blocks were nudged three pixels must not read as a board that changed.
 */
const IGNORED_PATHS = new Set(["x", "y", "rotation", "index", "parentId", "opacity"])

function asText(value: unknown): string {
  if (value === undefined || value === null) return ""
  if (typeof value === "string") return value
  if (typeof value === "number" || typeof value === "boolean") return String(value)
  return JSON.stringify(value)
}

function isShape(record: RecordLike): boolean {
  return record.typeName === "shape"
}

function shapesOfType(records: RecordMap, type: string): RecordLike[] {
  return Object.values(records).filter((record) => isShape(record) && record.type === type)
}

function portsOf(record: RecordLike): PortLike[] {
  const inputs = (record.props?.inputs as PortLike[] | undefined) ?? []
  const outputs = (record.props?.outputs as PortLike[] | undefined) ?? []
  return [...inputs, ...outputs]
}

/**
 * Resolve a cable's two ends from the binding records that hold it there.
 *
 * The endpoints are the only honest way to say a cable was *rewired*: its
 * `start`/`end` props are handle coordinates, which move whenever either Block
 * moves, so a coordinate diff would call every dragged board a rewiring.
 */
function cableEnds(records: RecordMap, cableId: string): CableEnds {
  const ends: CableEnds = { start: null, end: null }
  for (const record of Object.values(records)) {
    if (record.typeName !== "binding") continue
    if (record.type !== "connection") continue
    if (record.fromId !== cableId) continue
    const terminal = record.props?.terminal === "end" ? "end" : "start"
    ends[terminal] = {
      shapeId: record.toId ?? "",
      portId: asText(record.props?.portId),
    }
  }
  return ends
}

/**
 * A cable end's identity: which port on which shape, and nothing else.
 *
 * Deliberately NOT the display label. The label contains the host Block's
 * title, so comparing labels made every cable touching a renamed Block report
 * itself as rewired — three false rows on the review fixture, caught by
 * `compareFixture.test.ts`. Renaming a Block does not move a cable; identity
 * decides the change and the label only describes it.
 */
function endIdentity(end: CableEnd | null): string {
  if (!end) return ""
  return `${end.shapeId}::${end.portId}`
}

function endLabel(end: CableEnd | null, records: RecordMap): string {
  if (!end) return ""
  const host = records[end.shapeId]
  const title = asText(host?.props?.title) || end.shapeId.replace(/^shape:/, "")
  const port = portsOf(host ?? { id: "", typeName: "shape" }).find((p) => p.id === end.portId)
  return `${title}.${port?.name || end.portId}`
}

function blockLabel(record: RecordLike | undefined, fallbackId: string): string {
  if (!record) return fallbackId.replace(/^shape:/, "")
  const title = asText(record.props?.title)
  if (title) return title
  return `${record.type ?? "shape"} ${fallbackId.replace(/^shape:/, "").slice(0, 8)}`
}

function compareFields(before: RecordLike, after: RecordLike, paths: readonly string[]): FieldChange[] {
  const changes: FieldChange[] = []
  for (const path of paths) {
    if (IGNORED_PATHS.has(path)) continue
    const previous = asText(before.props?.[path])
    const current = asText(after.props?.[path])
    if (previous === current) continue
    changes.push({ path, before: previous, after: current })
  }
  return changes
}

function emptyTally(): Record<SubjectKind, SubjectTally> {
  return {
    block: { added: 0, removed: 0, modified: 0 },
    port: { added: 0, removed: 0, modified: 0 },
    cable: { added: 0, removed: 0, modified: 0 },
    shape: { added: 0, removed: 0, modified: 0 },
  }
}

/**
 * Compare two board record maps and return every change, in reading order.
 *
 * Order is Blocks first (each immediately followed by its own port rows, so a
 * nested table needs no second pass), then cables, then other shapes.
 */
export function compareBoards(before: RecordMap, after: RecordMap): BoardCompare {
  const changes: CompareChange[] = []
  const tally = emptyTally()

  /**
   * Every change names the ELEMENT it belongs to — a Block or a cable, never
   * a port.
   *
   * This is the grouping altitude Figma's Layers list and Simulink's
   * comparison tree both use, and it is derived here rather than recovered
   * downstream by splitting a dotted name: a Block called `run.predict` would
   * make that split ambiguous, and the display would silently group under the
   * wrong element. `parentId` is set on a port change and on nothing else, so
   * it already IS the rule — a port's element is its host Block.
   *
   * `element` defaults to the change's own name, which is right for a Block, a
   * cable and a shape and WRONG for a port — so every port push must pass it.
   * One of the three once did not, and grouped a modified port under its own
   * dotted path; `compareModel.test.ts` now covers all three operations at
   * once so a single forgetful site cannot pass again.
   */
  const push = (change: Omit<CompareChange, "element" | "elementId"> & { element?: string }) => {
    const full: CompareChange = {
      ...change,
      elementId: change.parentId ?? change.id,
      element: change.element ?? change.name,
    }
    changes.push(full)
    tally[full.subject][full.kind] += 1
  }

  // ---- Blocks, and the ports that hang off them -------------------------
  const blockIds = new Set<string>([
    ...shapesOfType(before, "block").map((r) => r.id),
    ...shapesOfType(after, "block").map((r) => r.id),
  ])

  for (const blockId of [...blockIds].sort()) {
    const blockBefore = before[blockId]
    const blockAfter = after[blockId]
    const changeId = `block:${blockId}`
    const name = blockLabel(blockAfter ?? blockBefore, blockId)

    if (!blockBefore && blockAfter) {
      push({
        id: changeId,
        subject: "block",
        kind: "added",
        name,
        parentId: null,
        anchorBefore: null,
        anchorAfter: blockId,
        portId: null,
        fields: [],
        recordBefore: null,
        recordAfter: blockAfter,
      })
      continue
    }
    if (blockBefore && !blockAfter) {
      push({
        id: changeId,
        subject: "block",
        kind: "removed",
        name,
        parentId: null,
        anchorBefore: blockId,
        anchorAfter: null,
        portId: null,
        fields: [],
        recordBefore: blockBefore,
        recordAfter: null,
      })
      continue
    }
    if (!blockBefore || !blockAfter) continue

    // The Block persisted. It is `modified` ONLY if one of its OWN fields
    // differs. A port it gained or lost is that port's change, never this
    // one — that is the whole point of the third state.
    const ownFields = compareFields(blockBefore, blockAfter, BLOCK_COMPARE_FIELDS)
    const blockRowEmitted = ownFields.length > 0
    if (blockRowEmitted) {
      push({
        id: changeId,
        subject: "block",
        kind: "modified",
        name,
        parentId: null,
        anchorBefore: blockId,
        anchorAfter: blockId,
        portId: null,
        fields: ownFields,
        recordBefore: blockBefore,
        recordAfter: blockAfter,
      })
    }

    const portsBefore = new Map(portsOf(blockBefore).map((port) => [port.id, port]))
    const portsAfter = new Map(portsOf(blockAfter).map((port) => [port.id, port]))
    const portIds = new Set([...portsBefore.keys(), ...portsAfter.keys()])

    for (const portId of [...portIds].sort()) {
      const portBefore = portsBefore.get(portId)
      const portAfter = portsAfter.get(portId)
      const portChangeId = `port:${blockId}:${portId}`
      // A port row hangs under its Block whether or not the Block itself
      // produced a row, so the table can always nest it.
      const parentId = changeId
      const portName = portAfter?.name || portBefore?.name || portId

      if (!portBefore && portAfter) {
        push({
          id: portChangeId,
          subject: "port",
          kind: "added",
          name: `${name}.${portName}`,
          parentId,
          element: name,
          anchorBefore: null,
          anchorAfter: blockId,
          portId,
          fields: [],
          recordBefore: null,
          recordAfter: portAfter,
        })
        continue
      }
      if (portBefore && !portAfter) {
        push({
          id: portChangeId,
          subject: "port",
          kind: "removed",
          name: `${name}.${portBefore.name || portId}`,
          parentId,
          element: name,
          // A removed port has no row on the after board to point at,
          // so it anchors on the before board only. The display must
          // not invent a position for it.
          anchorBefore: blockId,
          anchorAfter: null,
          portId,
          fields: [],
          recordBefore: portBefore,
          recordAfter: null,
        })
        continue
      }
      if (!portBefore || !portAfter) continue

      const portFields: FieldChange[] = []
      for (const path of PORT_COMPARE_FIELDS) {
        const previous = asText((portBefore as unknown as Record<string, unknown>)[path])
        const current = asText((portAfter as unknown as Record<string, unknown>)[path])
        if (previous === current) continue
        portFields.push({ path, before: previous, after: current })
      }
      if (portFields.length === 0) continue
      push({
        id: portChangeId,
        subject: "port",
        kind: "modified",
        name: `${name}.${portName}`,
        parentId,
        element: name,
        anchorBefore: blockId,
        anchorAfter: blockId,
        portId,
        fields: portFields,
        recordBefore: portBefore,
        recordAfter: portAfter,
      })
    }
  }

  // ---- Cables -----------------------------------------------------------
  const cableIds = new Set<string>([
    ...shapesOfType(before, "connection").map((r) => r.id),
    ...shapesOfType(after, "connection").map((r) => r.id),
  ])

  for (const cableId of [...cableIds].sort()) {
    const cableBefore = before[cableId]
    const cableAfter = after[cableId]
    const changeId = `cable:${cableId}`
    const endsBefore = cableEnds(before, cableId)
    const endsAfter = cableEnds(after, cableId)
    const label = (ends: CableEnds, records: RecordMap) => {
      const from = endLabel(ends.start, records)
      const to = endLabel(ends.end, records)
      return from || to ? `${from} → ${to}` : `cable ${cableId.replace(/^shape:/, "").slice(0, 8)}`
    }

    if (!cableBefore && cableAfter) {
      push({
        id: changeId,
        subject: "cable",
        kind: "added",
        name: label(endsAfter, after),
        parentId: null,
        anchorBefore: null,
        anchorAfter: cableId,
        portId: null,
        fields: [],
        recordBefore: null,
        recordAfter: cableAfter,
      })
      continue
    }
    if (cableBefore && !cableAfter) {
      push({
        id: changeId,
        subject: "cable",
        kind: "removed",
        name: label(endsBefore, before),
        parentId: null,
        anchorBefore: cableId,
        anchorAfter: null,
        portId: null,
        fields: [],
        recordBefore: cableBefore,
        recordAfter: null,
      })
      continue
    }
    if (!cableBefore || !cableAfter) continue

    const fields = compareFields(cableBefore, cableAfter, CABLE_COMPARE_FIELDS)
    // Rewiring is an endpoint fact, read off the bindings, never off the
    // handle coordinates — those move whenever a Block is dragged.
    for (const terminal of ["start", "end"] as const) {
      // Identity decides whether it moved; the label only says where to.
      if (endIdentity(endsBefore[terminal]) === endIdentity(endsAfter[terminal])) continue
      fields.push({
        path: `endpoint.${terminal}`,
        before: endLabel(endsBefore[terminal], before),
        after: endLabel(endsAfter[terminal], after),
      })
    }
    if (fields.length === 0) continue
    push({
      id: changeId,
      subject: "cable",
      kind: "modified",
      name: label(endsAfter, after),
      parentId: null,
      anchorBefore: cableId,
      anchorAfter: cableId,
      portId: null,
      fields,
      recordBefore: cableBefore,
      recordAfter: cableAfter,
    })
  }

  // ---- Every other shape, as a whole ------------------------------------
  const otherIds = new Set<string>()
  for (const records of [before, after]) {
    for (const record of Object.values(records)) {
      if (!isShape(record)) continue
      if (record.type === "block" || record.type === "connection") continue
      otherIds.add(record.id)
    }
  }

  for (const shapeId of [...otherIds].sort()) {
    const shapeBefore = before[shapeId]
    const shapeAfter = after[shapeId]
    const changeId = `shape:${shapeId}`
    const name = blockLabel(shapeAfter ?? shapeBefore, shapeId)
    if (!shapeBefore && shapeAfter) {
      push({
        id: changeId,
        subject: "shape",
        kind: "added",
        name,
        parentId: null,
        anchorBefore: null,
        anchorAfter: shapeId,
        portId: null,
        fields: [],
        recordBefore: null,
        recordAfter: shapeAfter,
      })
      continue
    }
    if (shapeBefore && !shapeAfter) {
      push({
        id: changeId,
        subject: "shape",
        kind: "removed",
        name,
        parentId: null,
        anchorBefore: shapeId,
        anchorAfter: null,
        portId: null,
        fields: [],
        recordBefore: shapeBefore,
        recordAfter: null,
      })
      continue
    }
    if (!shapeBefore || !shapeAfter) continue
    const paths = new Set<string>([...Object.keys(shapeBefore.props ?? {}), ...Object.keys(shapeAfter.props ?? {})])
    const fields = compareFields(shapeBefore, shapeAfter, [...paths].sort())
    if (fields.length === 0) continue
    push({
      id: changeId,
      subject: "shape",
      kind: "modified",
      name,
      parentId: null,
      anchorBefore: shapeId,
      anchorAfter: shapeId,
      portId: null,
      fields,
      recordBefore: shapeBefore,
      recordAfter: shapeAfter,
    })
  }

  return { changes, tally, total: changes.length }
}

/**
 * src/editor/propertyRows.ts — the row model behind the Compare dialog's
 * Properties table (docs/menus/screenshots/08).
 *
 * Byte-for-byte port of
 * /home/bam/systemsketch/src/compare/propertyRows.ts:1-247. Only its
 * `import type { CompareChange } from './compareModel'` resolves differently
 * here — it points at this directory's own `compareModel.ts` (see that
 * file's header for the one edit it carries: `BlockPort` inlined
 * structurally). Nothing in propertyRows.ts itself changed.
 */

/**
 * The row model behind the property table, ported from the omnibox variant.
 *
 * The `PropertyRow` union below, and the three accessors under it, are that
 * variant's `src/review/boardDiff.ts` verbatim — it is the model Zach picked
 * when he compared the five, and the discriminated union is the load-bearing
 * part: `added` has no `previous` KEY AT ALL, so "the value it used to have"
 * cannot be typed, let alone rendered. The three-state model enforced by the
 * compiler instead of by a convention.
 *
 * WHY the union is copied but its producer is not: omnibox computes these rows
 * from a hardcoded fixture (`reviewFixture.ts` — a demo with canned versions).
 * This track diffs REAL boards read off disk through `compareSource.ts`.
 * Importing omnibox's producer would have swapped live evidence for a mock, so
 * only the row SHAPE crossed over and `propertyRowsOf` below is the adapter
 * that feeds it from this tree's real `CompareChange`. The praised table and
 * the real data both survive; neither one had to win.
 */

import type { CompareChange } from "./compareModel"

/**
 * One row of the property comparison table.
 *
 * A discriminated union, on purpose. `added` has no `previous` key at all, so
 * "the value it used to have" cannot be typed, let alone rendered.
 */
export type PropertyRow =
  | {
      readonly key: string
      readonly state: "added"
      /** The element this row belongs to — a Block or a cable, never a port. */
      readonly element: string
      readonly elementId: string
      /** What changed inside that element: a port, a field, or `port · field`. */
      readonly property: string
      readonly current: string
    }
  | {
      readonly key: string
      readonly state: "removed"
      readonly element: string
      readonly elementId: string
      readonly property: string
      readonly previous: string
    }
  | {
      readonly key: string
      readonly state: "modified"
      readonly element: string
      readonly elementId: string
      readonly property: string
      readonly previous: string
      readonly current: string
    }

/** Read a row's previous value, or `null` where the row asserts absence. */
export function rowPrevious(row: PropertyRow): string | null {
  return row.state === "added" ? null : row.previous
}

/** Read a row's current value, or `null` where the row asserts absence. */
export function rowCurrent(row: PropertyRow): string | null {
  return row.state === "removed" ? null : row.current
}

/**
 * Only a `modified` row has two values to compare, so only a `modified` row can
 * carry a word-level highlight. GitHub's asymmetry rule, one level up: a pure
 * addition has no "green nothing" on the other side to diff against.
 */
export function rowSupportsWordDiff(row: PropertyRow): row is Extract<PropertyRow, { state: "modified" }> {
  return row.state === "modified"
}

/** The state badge's copy, matching the omnibox variant's `OPERATION_LABEL`. */
export const STATE_LABEL: Readonly<Record<PropertyRow["state"], string>> = {
  added: "Added",
  removed: "Removed",
  modified: "Modified",
}

/**
 * Sort order for the flattened table: added, then removed, then modified.
 *
 * Ported from omnibox's `STATE_ORDER`. Insertions and deletions are the coarse
 * findings a reviewer wants first; a modification is the one they have to read
 * a value to understand, so it reads last.
 */
const STATE_ORDER: Readonly<Record<string, number>> = {
  added: 0,
  removed: 1,
  modified: 2,
}

/** What a whole-object insertion or deletion says in its one populated cell. */
function describeWhole(change: CompareChange, side: "before" | "after"): string {
  const record = side === "before" ? change.recordBefore : change.recordAfter
  if (!record || typeof record !== "object") return change.name
  const props = (record as { props?: Record<string, unknown> }).props ?? record
  const bag = props as Record<string, unknown>
  const parts: string[] = []
  for (const key of ["name", "title", "type", "blockType", "defaultValue"]) {
    const value = bag[key]
    if (typeof value !== "string" || value === "") continue
    parts.push(key === "defaultValue" ? `= ${value}` : value)
  }
  return parts.join(" · ") || change.name
}

/**
 * What a port change is called INSIDE its element.
 *
 * Sliced by the element's own length rather than split on the first `.`, so a
 * Block legitimately named `run.predict` still yields its port name and not the
 * tail of its own title.
 */
function withinElement(change: CompareChange): string | null {
  if (change.subject !== "port") return null
  const prefix = `${change.element}.`
  return change.name.startsWith(prefix) ? change.name.slice(prefix.length) : change.name
}

/**
 * The `Property` column — what changed inside the element.
 *
 * A port and a field are different depths of the same address, so they compose:
 * a retitled Block is `title`, a renamed port is `image`, and a port whose type
 * changed is `image · type`. A whole-object insertion has no property under it
 * at all, and says so with the noun rather than inventing a field name.
 */
function propertyOf(change: CompareChange, path: string | null): string {
  const within = withinElement(change)
  if (path && within) return `${within} · ${path}`
  if (path) return path
  if (within) return within
  return change.subject
}

/** Every row one change contributes, in the omnibox row shape. */
export function propertyRowsOf(change: CompareChange): PropertyRow[] {
  const at = { element: change.element, elementId: change.elementId }
  if (change.kind === "added") {
    return [
      {
        key: change.id,
        state: "added",
        ...at,
        property: propertyOf(change, null),
        current: describeWhole(change, "after"),
      },
    ]
  }
  if (change.kind === "removed") {
    return [
      {
        key: change.id,
        state: "removed",
        ...at,
        property: propertyOf(change, null),
        previous: describeWhole(change, "before"),
      },
    ]
  }
  // A `modified` change with no field pairs cannot say what changed, so it
  // falls back to its whole-object description on both sides rather than
  // rendering an empty pair — which would read as "both sides are blank".
  if (change.fields.length === 0) {
    return [
      {
        key: change.id,
        state: "modified",
        ...at,
        property: propertyOf(change, null),
        previous: describeWhole(change, "before"),
        current: describeWhole(change, "after"),
      },
    ]
  }
  return change.fields.map((field) => ({
    key: `${change.id}:${field.path}`,
    state: "modified" as const,
    ...at,
    property: propertyOf(change, field.path),
    previous: field.before,
    current: field.after,
  }))
}

/**
 * One entry in the Figma-style element list.
 *
 * `status` is deliberately Figma's vocabulary — Added · Edited · Removed — and
 * NOT the table's Added/Removed/Modified. They are different claims at
 * different altitudes: a Block that only gained a port was not itself modified,
 * but it WAS edited, and "Edited" is the word that covers "something under this
 * changed" without asserting the element's own fields moved. The property rows
 * underneath keep the precise three-state vocabulary.
 */
export interface ElementSummary {
  readonly id: string
  readonly name: string
  readonly subject: CompareChange["subject"]
  readonly status: "added" | "edited" | "removed"
  readonly changes: readonly CompareChange[]
  readonly rowCount: number
}

export const ELEMENT_STATUS_LABEL: Readonly<Record<ElementSummary["status"], string>> = {
  added: "Added",
  edited: "Edited",
  removed: "Removed",
}

/**
 * Aggregate the flat change list into the elements a person actually points at.
 *
 * Insertion order follows `orderChanges`, so the list reads added → removed →
 * edited the same way the flat table does; an element is placed by the first
 * change that mentions it.
 */
export function elementSummaries(changes: readonly CompareChange[]): ElementSummary[] {
  const byElement = new Map<string, CompareChange[]>()
  for (const change of orderChanges(changes)) {
    const list = byElement.get(change.elementId) ?? []
    list.push(change)
    byElement.set(change.elementId, list)
  }
  const summaries: ElementSummary[] = []
  for (const [id, group] of byElement) {
    // The element's OWN change, if it has one. A Block that only gained a
    // port contributes no such change, and is `edited` by its children.
    const own = group.find((change) => change.id === id)
    const status: ElementSummary["status"] =
      own?.kind === "added" ? "added" : own?.kind === "removed" ? "removed" : "edited"
    summaries.push({
      id,
      name: group[0].element,
      subject: own?.subject ?? group[0].subject,
      status,
      changes: group,
      rowCount: group.reduce((total, change) => total + propertyRowsOf(change).length, 0),
    })
  }
  return summaries
}

/** The changes, ordered the way the ported table lists them. */
export function orderChanges(changes: readonly CompareChange[]): CompareChange[] {
  return [...changes].sort((a, b) => (STATE_ORDER[a.kind] ?? 9) - (STATE_ORDER[b.kind] ?? 9))
}

"use client"

import { useCallback, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent } from "react"
import { ArrowRight, Box, Circle, Frame, Shapes, Square, Type, Waypoints, type LucideIcon } from "lucide-react"

import { cn } from "../lib/utils"
import { wordDiff, type DiffToken } from "./wordDiff"
import type { CompareChange, SubjectKind } from "./compareModel"
import {
  elementSummaries,
  orderChanges,
  propertyRowsOf,
  rowCurrent,
  rowPrevious,
  rowSupportsWordDiff,
  ELEMENT_STATUS_LABEL,
  STATE_LABEL,
  type ElementSummary,
  type PropertyRow,
} from "./propertyRows"
import { ToggleGroup, ToggleGroupItem } from "../components/toggle-group"

/**
 * src/editor/propertyTable.tsx — the Compare dialog's Properties view:
 * the "By element"/"Flat table" layout switch, the word-diff toggle, and
 * the table itself (docs/menus/screenshots/08-compare-changes.png).
 *
 * Ported from /home/bam/systemsketch/src/compare/PropertyTable.tsx:1-583,
 * itself ported from the omnibox variant's `src/review/DiffReviewModal.tsx`
 * (`TokenRun`/`ValueCell` verbatim, down to the visual language — "I like
 * the property table in omnibox" is why the class-name provenance is kept
 * as a namespace split in the donor's `review-table.css`, restated below as
 * a comment rather than a second stylesheet namespace since Tailwind has no
 * such split to make).
 *
 * ONE deliberate shape change from the donor, called out because it moves a
 * seam: the donor's `CompareDialog.tsx:848-869` mounted the word-diff
 * checkbox and the layout segmented control OUTSIDE `PropertyTable`, in the
 * dialog shell, and only ever passed `gitHighlight`/`layout` down as
 * read-only props. Per this kit's brief ("propertyTable.tsx — the right
 * rail's Properties view"), both controls move IN: `PropertyTable` now owns
 * its own header and is handed `onGitHighlightChange`/`onLayoutChange`
 * callbacks so the host (`compareReview.tsx`) still owns the state — same
 * host contract, one fewer thing every host has to hand-wire to get "the
 * Properties view" on screen.
 *
 * The three-state colour law travels unparaphrased from `review-table.css`:
 * Added/Removed are GitHub's green/red; the third state is blue, not amber,
 * because
 *
 *   "Blue is much clearer than orange. […] for colors those are very
 *    orthogonal in space RGB right, so blue is natural for a third color."
 *
 * — red, green and blue are the orthogonal axes, and amber sat close enough
 * to red to read as a weak deletion. This app's stock shadcn theme carries
 * no bespoke success/accent-third-state tokens (checked: only
 * `--destructive` exists), so the three states are plain Tailwind
 * green-600/red-600/blue-600 (light) and their -400 dark counterparts,
 * following the same direct-palette convention `packages/inspector`'s
 * `StockCheckReport.tsx` already uses for its own tri-state banners — not a
 * new bbox-specific colour token.
 */

export type TableLayout = "columns" | "figma"

/**
 * The element-list column's width, in the `figma` layout.
 *
 * `DEFAULT` is wide enough to read an ordinary single name ("Controller",
 * "Button 001") without ellipsising, matching Figma's own Layers panel —
 * the reference this layout is deliberately copied from. A compound name
 * like the donor's own `"Plannerv2.plan → Controller.plan"` still won't fit
 * and still ellipsises; that is expected, and Figma's own panel does the
 * same for a name that long.
 *
 * `MIN` is the point below which the row's fixed furniture (icon, count,
 * status chip, and the button's own padding) already eats ~110px, leaving
 * too little for any name to be worth showing at all. `MAX` is the point
 * past which the property table's own Previous/Current columns — the
 * values a reviewer is actually there to read — would be squeezed for the
 * sake of an index list.
 */
const DEFAULT_LIST_WIDTH = 220
const MIN_LIST_WIDTH = 150
const MAX_LIST_WIDTH = 440

/**
 * Which glyph stands for a change's underlying record.
 *
 * Zach's complaint was that a Block, a cable and a stock shape all read as
 * the same anonymous row — "it wasn't clear to me that one was like an
 * edge, one was a node, one was like a rectangle primitive". A
 * `block`/`cable`/`port` subject already says enough on its own; a `shape`
 * subject is this kit's catch-all for every other primitive, so it has to
 * look one level deeper — at the record's own `.type` — to tell a
 * rectangle from a text box from a frame. `Shapes` is the fallback for a
 * stock type this table has no specific glyph for yet, not for "unknown"
 * in general.
 */
function elementIcon(subject: SubjectKind, record: unknown): LucideIcon {
  if (subject === "block") return Box
  if (subject === "cable") return Waypoints
  if (subject === "port") return Circle
  const shapeType = record && typeof record === "object" ? (record as { type?: unknown }).type : undefined
  switch (shapeType) {
    case "text":
      return Type
    case "frame":
      return Frame
    case "arrow":
      return ArrowRight
    case "geo":
      return Square
    default:
      return Shapes
  }
}

/** The record `elementIcon` should read for one flattened property row. */
function rowIcon(change: CompareChange): LucideIcon {
  return elementIcon(change.subject, change.recordAfter ?? change.recordBefore)
}

/**
 * The record `elementIcon` should read for a Figma-list element entry.
 *
 * An element's own change (its id matches the element id) carries the
 * record that actually says what kind of thing it is; a Block that only
 * gained a port has no such change, but `Box` is right for it regardless
 * because `subject` is already `"block"` in that case (`elementSummaries`
 * computes it the same way).
 */
function summaryIcon(element: ElementSummary): LucideIcon {
  const own = element.changes.find((change) => change.id === element.id) ?? element.changes[0]
  return elementIcon(element.subject, own?.recordAfter ?? own?.recordBefore)
}

/** Small, muted — the icon states WHAT changed; the badge states HOW. */
function ElementIcon({ Icon }: { Icon: LucideIcon }) {
  return <Icon className="size-[13px] shrink-0 text-muted-foreground" strokeWidth={2} aria-hidden="true" />
}

function TokenRun({ tokens }: { tokens: readonly DiffToken[] }) {
  return (
    <>
      {tokens.map((token, index) =>
        token.kind === "same" ? (
          <span key={index}>{token.text}</span>
        ) : (
          <mark
            key={index}
            data-token={token.kind}
            className={cn(
              "rounded-[3px] px-px py-px font-extrabold text-foreground",
              // Highlight, never strikethrough — the substring that
              // actually differs takes a stronger fill; the cell itself is
              // NOT recoloured (GitHub's own word-diff rule).
              token.kind === "removed" && "bg-red-100 shadow-[inset_0_-2px_var(--color-red-600)] dark:bg-red-950 dark:shadow-[inset_0_-2px_var(--color-red-400)]",
              token.kind === "added" && "bg-green-100 shadow-[inset_0_-2px_var(--color-green-600)] dark:bg-green-950 dark:shadow-[inset_0_-2px_var(--color-green-400)]",
            )}
          >
            {token.text}
          </mark>
        ),
      )}
    </>
  )
}

/**
 * One cell of the Previous/Current pair.
 *
 * Word-level highlight fires only where both sides exist — a `modified`
 * row. On an `added` or `removed` row the other side is genuinely absent,
 * and the cell says so with an explicit absence mark rather than going
 * blank: empty reads as "unknown", and absence is the entire claim the row
 * is making.
 */
function ValueCell({ row, side, gitHighlight }: { row: PropertyRow; side: "previous" | "current"; gitHighlight: boolean }) {
  const value = side === "previous" ? rowPrevious(row) : rowCurrent(row)
  if (value === null) {
    return (
      <td
        className="bg-[repeating-linear-gradient(-45deg,transparent,transparent_5px,var(--color-muted)_5px,var(--color-muted)_10px)] p-2 align-top break-words"
        data-absent="true"
      >
        <span className="font-bold text-muted-foreground/70" aria-label="not present">
          —
        </span>
      </td>
    )
  }
  const sideWash = gitHighlight
    ? side === "previous"
      ? "bg-red-600/10"
      : "bg-green-600/10"
    : undefined
  if (rowSupportsWordDiff(row)) {
    const diff = wordDiff(row.previous, row.current)
    return (
      <td className={cn("p-2 align-top break-words", sideWash)} data-side={side}>
        <code className="font-mono text-[11px] break-words text-foreground">
          <TokenRun tokens={side === "previous" ? diff.before : diff.after} />
        </code>
      </td>
    )
  }
  return (
    <td className={cn("p-2 align-top break-words", sideWash)} data-side={side}>
      <code className="font-mono text-[11px] break-words text-foreground">{value}</code>
    </td>
  )
}

const STATE_COLORS: Record<PropertyRow["state"], string> = {
  added: "border-green-600 bg-green-100 dark:border-green-400 dark:bg-green-950",
  removed: "border-red-600 bg-red-100 dark:border-red-400 dark:bg-red-950",
  modified: "border-blue-600 bg-blue-100 dark:border-blue-400 dark:bg-blue-950",
}

const ROW_RAIL_COLORS: Record<PropertyRow["state"], string> = {
  added: "shadow-[inset_3px_0_var(--color-green-600)] dark:shadow-[inset_3px_0_var(--color-green-400)]",
  removed: "shadow-[inset_3px_0_var(--color-red-600)] dark:shadow-[inset_3px_0_var(--color-red-400)]",
  modified: "shadow-[inset_3px_0_var(--color-blue-600)] dark:shadow-[inset_3px_0_var(--color-blue-400)]",
}

/** The state badge, in the Layer/Property cell. */
function StateBadge({ state }: { state: PropertyRow["state"] }) {
  return (
    <span
      data-state={state}
      className={cn(
        "shrink-0 rounded-[5px] border px-[7px] py-0.5 font-mono text-[9px] font-bold tracking-[0.06em] text-foreground uppercase",
        STATE_COLORS[state],
      )}
    >
      {STATE_LABEL[state]}
    </span>
  )
}

/**
 * The accept/reject affordance, present ONLY when the dialog was opened to
 * apply something (Merge, Rebase). A plain review passes nothing and this
 * table renders no checkbox at all — not a disabled one, not a hidden one.
 *
 * The unit is the ELEMENT, not the property row: a Block whose title and
 * two ports all changed is one thing a reviewer decides about, not three.
 */
export interface ElementReview {
  isAccepted(elementId: string): boolean
  onToggle(elementId: string, accepted: boolean): void
}

/** The checkbox itself, shared by both layouts so they cannot drift apart. */
function AcceptBox({
  review,
  elementId,
  elementName,
  testid,
  className,
}: {
  review: ElementReview
  elementId: string
  elementName: string
  testid: string
  className?: string
}) {
  const accepted = review.isAccepted(elementId)
  return (
    <input
      type="checkbox"
      className={cn("size-[13px] shrink-0 accent-primary", className)}
      data-testid={testid}
      checked={accepted}
      aria-label={`Include ${elementName}`}
      // The row underneath is a select-this-element control; a click on
      // the box must decide inclusion WITHOUT also moving the boards, or
      // every tick would drag the camera somewhere the reviewer did not
      // ask to go.
      onClick={(event) => event.stopPropagation()}
      onChange={(event) => review.onToggle(elementId, event.target.checked)}
    />
  )
}

interface RowProps {
  change: CompareChange
  row: PropertyRow
  selected: boolean
  onSelect: (changeId: string) => void
  gitHighlight: boolean
  /** `columns` prints the element beside the property; `figma` does not. */
  showElement: boolean
  /** Action mode only, and only ever rendered in the element cell. */
  review?: ElementReview
}

function ValueRow({ change, row, selected, onSelect, gitHighlight, showElement, review }: RowProps) {
  return (
    <tr
      data-state={row.state}
      data-testid={`compare-row-${row.key}`}
      data-change-id={change.id}
      data-element-id={row.elementId}
      data-selected={selected || undefined}
      tabIndex={0}
      role="button"
      aria-label={`${STATE_LABEL[row.state]} · ${row.element} · ${row.property}`}
      className={cn(
        "cursor-pointer",
        ROW_RAIL_COLORS[row.state],
        selected ? "bg-blue-600/10 outline outline-1 -outline-offset-1 outline-blue-600 dark:outline-blue-400" : "hover:bg-muted/60",
      )}
      onClick={() => onSelect(change.id)}
      onKeyDown={(event) => {
        if (event.key !== "Enter" && event.key !== " ") return
        event.preventDefault()
        onSelect(change.id)
      }}
    >
      {showElement ? (
        <th scope="row" className="flex items-center gap-1.5 p-2 align-top font-semibold break-words">
          <ElementIcon Icon={rowIcon(change)} />
          <span className="min-w-0 flex-1 overflow-hidden text-[11px] font-[650] text-ellipsis whitespace-nowrap text-foreground" title={row.element}>
            {row.element}
          </span>
          <StateBadge state={row.state} />
          {review ? (
            <AcceptBox review={review} elementId={row.elementId} elementName={row.element} testid={`compare-accept-row-${row.key}`} />
          ) : null}
        </th>
      ) : null}
      <td className="p-2 align-top break-words">
        {/*
         * Figma puts the state to the RIGHT of the name, on the same line —
         * not stacked above it. The inner flex `<div>` is deliberate: a
         * `<td>` given `display:flex` drops out of the table's column
         * layout and the browser wraps it in an anonymous cell, silently
         * moving this text under the wrong header. The `<td>` stays a real
         * table cell; only its content is a flex row.
         */}
        <div className="flex min-w-0 items-center gap-2">
          <span className="min-w-0 flex-1 overflow-hidden font-mono text-[11px] text-ellipsis whitespace-nowrap text-foreground" title={row.property}>
            {row.property}
          </span>
          {/* With no Element column the badge has nowhere else to live, and
           *  dropping it would take the row's state with it. */}
          {showElement ? null : <StateBadge state={row.state} />}
        </div>
      </td>
      <ValueCell row={row} side="previous" gitHighlight={gitHighlight} />
      <ValueCell row={row} side="current" gitHighlight={gitHighlight} />
    </tr>
  )
}

export interface PropertyTableProps {
  changes: readonly CompareChange[]
  selectedId: string | null
  onSelect: (changeId: string) => void
  /** Whether the two-layer git-style ink is painted. */
  gitHighlight: boolean
  onGitHighlightChange: (next: boolean) => void
  layout: TableLayout
  onLayoutChange: (next: TableLayout) => void
  /** `figma` only: which element's properties the right-hand table shows. */
  selectedElementId: string | null
  onSelectElement: (elementId: string | null) => void
  /** Present only when the dialog was opened to APPLY something. */
  review?: ElementReview
}

/**
 * The header row above the table: the word-diff toggle and the "By
 * element"/"Flat table" switch. Donor: `CompareDialog.tsx:958-993`, moved
 * here per this file's header note.
 */
function PropertyTableOptions({
  gitHighlight,
  onGitHighlightChange,
  layout,
  onLayoutChange,
}: Pick<PropertyTableProps, "gitHighlight" | "onGitHighlightChange" | "layout" | "onLayoutChange">) {
  return (
    <div className="flex items-center gap-3 border-b border-border px-3 py-2">
      <label
        className="flex cursor-pointer items-center gap-1.5 text-[11px] font-semibold text-muted-foreground select-none hover:text-foreground"
        data-testid="compare-highlight-toggle"
      >
        <input
          type="checkbox"
          className="accent-primary"
          checked={gitHighlight}
          data-testid="compare-highlight-checkbox"
          onChange={(event) => onGitHighlightChange(event.target.checked)}
        />
        Word-level diff highlighting
        <small className="ml-auto text-[10px] font-medium text-muted-foreground/70">
          {gitHighlight ? "on" : "off · like Figma"}
        </small>
      </label>
      {/* Two real layouts over the same rows, switchable in place — the
       *  point is to be able to judge them against each other without
       *  leaving the board. */}
      <ToggleGroup
        value={[layout]}
        onValueChange={(next) => {
          const value = next[0]
          if (value) onLayoutChange(value as TableLayout)
        }}
        aria-label="Table layout"
        className="ml-auto"
      >
        <ToggleGroupItem value="figma" variant="outline" size="sm" data-testid="compare-layout-figma">
          By element
        </ToggleGroupItem>
        <ToggleGroupItem value="columns" variant="outline" size="sm" data-testid="compare-layout-columns">
          Flat table
        </ToggleGroupItem>
      </ToggleGroup>
    </div>
  )
}

export function PropertyTable({
  changes,
  selectedId,
  onSelect,
  gitHighlight,
  onGitHighlightChange,
  layout,
  onLayoutChange,
  selectedElementId,
  onSelectElement,
  review,
}: PropertyTableProps) {
  const ordered = orderChanges(changes)

  return (
    <div className="flex min-h-0 flex-1 flex-col" data-testid="compare-property-table-view">
      <PropertyTableOptions
        gitHighlight={gitHighlight}
        onGitHighlightChange={onGitHighlightChange}
        layout={layout}
        onLayoutChange={onLayoutChange}
      />
      {layout === "figma" ? (
        <FigmaLayout
          changes={changes}
          selectedId={selectedId}
          onSelect={onSelect}
          gitHighlight={gitHighlight}
          selectedElementId={selectedElementId}
          onSelectElement={onSelectElement}
          review={review}
        />
      ) : (
        <div className="isolate min-h-0 flex-1 overflow-auto">
          <table className="w-full table-fixed border-collapse text-xs" data-testid="compare-property-table" data-layout="columns">
            <thead className="sticky top-0 z-10 bg-card">
              <tr>
                {["Element", "Property", "Previous", "Current"].map((heading) => (
                  <th
                    key={heading}
                    scope="col"
                    className="border-b border-border p-2 text-left font-mono text-[9px] font-bold tracking-[0.09em] text-muted-foreground/80 uppercase"
                  >
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {ordered.flatMap((change) =>
                propertyRowsOf(change).map((row) => (
                  <ValueRow
                    key={row.key}
                    change={change}
                    row={row}
                    selected={change.id === selectedId}
                    onSelect={onSelect}
                    gitHighlight={gitHighlight}
                    showElement
                    review={review}
                  />
                )),
              )}
              {changes.length === 0 ? (
                <tr>
                  <td colSpan={4} className="p-7 text-center text-muted-foreground" data-testid="compare-no-changes">
                    These two versions are identical.
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

/**
 * Figma's layout, copied rather than approximated.
 *
 * A left list of the elements that changed, each badged; the right side is
 * the property comparison for exactly one of them. The empty-state
 * sentence is Figma's own wording, which is the point — this view exists to
 * be judged against the tool it came from, so paraphrasing it would blur
 * the comparison.
 */
function FigmaLayout({
  changes,
  selectedId,
  onSelect,
  gitHighlight,
  selectedElementId,
  onSelectElement,
  review,
}: Omit<PropertyTableProps, "layout" | "onLayoutChange" | "onGitHighlightChange">) {
  const elements = elementSummaries(changes)
  const active = elements.find((element) => element.id === selectedElementId) ?? null

  // WHY: session-only, not persisted. Nothing else a host remembers about
  // this dialog (mode, dock, layout, gitHighlight) survives a reopen either
  // — they are all plain state on the host — so this control doesn't get to
  // be the first exception.
  const [listWidth, setListWidth] = useState(DEFAULT_LIST_WIDTH)
  const [dragging, setDragging] = useState(false)
  const dragOrigin = useRef<{ pointerX: number; startWidth: number } | null>(null)

  const clampListWidth = (width: number) => Math.min(MAX_LIST_WIDTH, Math.max(MIN_LIST_WIDTH, width))

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      event.currentTarget.setPointerCapture(event.pointerId)
      dragOrigin.current = { pointerX: event.clientX, startWidth: listWidth }
      setDragging(true)
    },
    [listWidth],
  )

  const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const origin = dragOrigin.current
    if (!origin) return
    const delta = event.clientX - origin.pointerX
    setListWidth(clampListWidth(origin.startWidth + delta))
  }, [])

  const endDrag = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    dragOrigin.current = null
    setDragging(false)
  }, [])

  return (
    <div
      className="grid min-h-0 flex-1 overflow-hidden"
      data-testid="compare-figma-layout"
      style={{ gridTemplateColumns: `${listWidth}px 6px minmax(0, 1fr)` } as CSSProperties}
    >
      <ul
        className="m-0 list-none overflow-y-auto border-r border-border bg-muted/40 p-1.5"
        data-testid="compare-element-list"
        data-review={review ? "on" : undefined}
      >
        {elements.map((element) => (
          <li key={element.id} className={cn("mb-[3px]", review && "flex items-center gap-1")}>
            <button
              type="button"
              data-testid={`compare-element-${element.id}`}
              data-status={element.status}
              data-selected={element.id === selectedElementId || undefined}
              aria-pressed={element.id === selectedElementId}
              // A cable's name is both endpoints, which will not fit an
              // index column. It ellipsises, so the complete value has to
              // stay one hover away — a clipped name must never be the
              // only copy.
              title={element.name}
              className={cn(
                "flex w-full min-w-0 items-center gap-1.5 rounded-[7px] border border-transparent px-1.5 py-1.5 text-left text-[11px] text-foreground hover:bg-muted",
                review && "flex-1",
                element.id === selectedElementId && "border-blue-600 bg-blue-600/10 dark:border-blue-400",
              )}
              onClick={() => onSelectElement(element.id === selectedElementId ? null : element.id)}
            >
              <ElementIcon Icon={summaryIcon(element)} />
              <span className="min-w-0 flex-1 overflow-hidden font-[650] text-ellipsis whitespace-nowrap">{element.name}</span>
              <span className="shrink-0 font-mono text-[10px] tabular-nums text-muted-foreground/80">{element.rowCount}</span>
              <span
                data-status={element.status}
                className={cn(
                  "shrink-0 rounded-[5px] border px-1.5 py-0.5 font-mono text-[9px] font-bold tracking-[0.06em] text-foreground uppercase",
                  element.status === "added" && "border-green-600 bg-green-100 dark:border-green-400 dark:bg-green-950",
                  element.status === "removed" && "border-red-600 bg-red-100 dark:border-red-400 dark:bg-red-950",
                  element.status === "edited" && "border-blue-600 bg-blue-100 dark:border-blue-400 dark:bg-blue-950",
                )}
              >
                {ELEMENT_STATUS_LABEL[element.status]}
              </span>
            </button>
            {/*
             * TRAILING, and a sibling of the row button rather than a
             * child. A child is invalid HTML — an `<input>` inside a
             * `<button>` — and the browser would route one click to both,
             * so ticking the box would also select (or DESELECT) the
             * element. Trailing because the row already opens with a 13px
             * kind glyph — a leading checkbox beside it reads as two
             * checkboxes, one mysteriously unticked.
             */}
            {review ? (
              <AcceptBox review={review} elementId={element.id} elementName={element.name} testid={`compare-accept-${element.id}`} />
            ) : null}
          </li>
        ))}
        {elements.length === 0 ? (
          <li className="p-7 text-center text-muted-foreground" data-testid="compare-no-changes">
            These two versions are identical.
          </li>
        ) : null}
      </ul>

      {/*
       * `onPointerDown` captures the pointer so the drag keeps tracking
       * even once the cursor leaves this 6px strip — without capture, a
       * fast drag outside the handle's own bounding box would silently
       * stop updating. Double-click resets to the default width. This is
       * panel-internal geometry (it measures only its own drag track), the
       * one exception the brief carves out of "no self-measurement".
       */}
      <div
        className="group/resize relative h-full cursor-col-resize touch-none bg-transparent"
        data-testid="compare-element-list-resize"
        data-dragging={dragging || undefined}
        role="separator"
        aria-orientation="vertical"
        aria-label="Resize the element list"
        aria-valuenow={listWidth}
        aria-valuemin={MIN_LIST_WIDTH}
        aria-valuemax={MAX_LIST_WIDTH}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onDoubleClick={() => setListWidth(DEFAULT_LIST_WIDTH)}
      >
        <span
          className={cn(
            "absolute top-0 bottom-0 left-0.5 w-0.5 rounded-sm bg-transparent group-hover/resize:bg-blue-600/60 dark:group-hover/resize:bg-blue-400/60",
            dragging && "bg-blue-600 dark:bg-blue-400",
          )}
        />
      </div>

      {active ? (
        <div className="isolate min-h-0 overflow-auto">
          <table className="w-full table-fixed border-collapse text-xs" data-testid="compare-property-table" data-layout="figma">
            <thead className="sticky top-0 z-10 bg-card">
              <tr>
                {["Property", "Previous", "Current"].map((heading) => (
                  <th
                    key={heading}
                    scope="col"
                    className="border-b border-border p-2 text-left font-mono text-[9px] font-bold tracking-[0.09em] text-muted-foreground/80 uppercase"
                  >
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {/* No `review` here on purpose: this table is already scoped
               *  to ONE element, whose box lives on its row in the list to
               *  the left. Repeating it per property would imply a
               *  property-level decision that no action can honour. */}
              {active.changes.flatMap((change) =>
                propertyRowsOf(change).map((row) => (
                  <ValueRow
                    key={row.key}
                    change={change}
                    row={row}
                    selected={change.id === selectedId}
                    onSelect={onSelect}
                    gitHighlight={gitHighlight}
                    showElement={false}
                  />
                )),
              )}
            </tbody>
          </table>
        </div>
      ) : (
        <p className="m-0 grid content-center justify-items-center p-6 text-center text-xs text-muted-foreground" data-testid="compare-figma-empty">
          Select an edited element to compare changes
        </p>
      )}
    </div>
  )
}

/**
 * src/editor/wordDiff.ts — the "Word-level diff highlighting · like
 * Figma" toggle in the Compare dialog (docs/menus/screenshots/08).
 *
 * Byte-for-byte port of
 * /home/bam/systemsketch/src/diff/wordDiff.ts:1-197 — already zero imports,
 * no React, no DOM, no colour. Nothing changed.
 */

/**
 * The intra-value diff, which is the whole point of round 2.
 *
 * Round 1 could say a field *changed*. It could not say what about it changed,
 * because the only thing a primitive carried was one `state` enum — so the
 * loudest mark available was a strike through the whole old value. A reader of
 * `git diff` never accepts that: on a delete+insert pair GitHub tokenizes both
 * sides and highlights the tokens that actually differ, layered on top of the
 * line-level red and green. `run_inference` → `run_predict` should put ink on
 * `inference` and `predict`, not on `run_`.
 *
 * This module is that tokenizer and that alignment, and nothing else. It has no
 * React, no DOM and no colour in it: it answers which runs of two strings are
 * shared and which are not, and the paint layer decides what that looks like.
 */

export type DiffTokenKind = "same" | "removed" | "added"

export interface DiffToken {
  readonly text: string
  readonly kind: DiffTokenKind
}

export interface WordDiff {
  /** The before value, every token marked `same` or `removed`. */
  readonly before: readonly DiffToken[]
  /** The after value, every token marked `same` or `added`. */
  readonly after: readonly DiffToken[]
  /** False when the two values are identical — the caller should draw nothing. */
  readonly changed: boolean
}

/**
 * Beyond this many tokens the alignment stops being worth its quadratic cost
 * *and* stops being worth reading: a Block description that differs in eighty
 * places is a rewrite, and a rewrite is honestly drawn as one whole-value
 * replacement rather than as confetti.
 */
export const WORD_DIFF_TOKEN_LIMIT = 160

/**
 * Split a field value the way a person reads an identifier.
 *
 * Runs of letters and digits are one token; runs of anything else — `_`, `.`,
 * `[`, a space — are another, and they are *kept*, because dropping them would
 * make `a.b` and `ab` align. Inside an alphanumeric run a camelCase boundary
 * splits again, so `runInference` → `runPredict` marks `Inference`, not the
 * whole word. A digit stays welded to the letters before it, which is what
 * keeps `v2` one token instead of two.
 */
export function tokenizeFieldValue(value: string): string[] {
  if (value === "") return []
  const runs = value.match(/[A-Za-z0-9]+|[^A-Za-z0-9]+/g) ?? []
  const tokens: string[] = []
  for (const run of runs) {
    if (!/^[A-Za-z0-9]/.test(run)) {
      tokens.push(run)
      continue
    }
    // A lower-to-upper step is a word boundary; a digit is not, so `v2`
    // survives whole and `parseHTTPBody` splits at the humps a reader sees.
    for (const part of run.split(/(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])/)) {
      if (part !== "") tokens.push(part)
    }
  }
  return tokens
}

/** Adjacent tokens of one kind become one span, so the DOM stays small. */
function coalesce(tokens: readonly DiffToken[]): DiffToken[] {
  const merged: DiffToken[] = []
  for (const token of tokens) {
    const last = merged[merged.length - 1]
    if (last && last.kind === token.kind) {
      merged[merged.length - 1] = { text: last.text + token.text, kind: last.kind }
    } else {
      merged.push(token)
    }
  }
  return merged
}

/** Longest common subsequence over tokens — the same alignment `diff` uses. */
function commonSubsequence(before: readonly string[], after: readonly string[]): boolean[][] {
  const rows = before.length
  const columns = after.length
  // `lengths[i][j]` is the LCS of the two suffixes starting at i and j.
  const lengths: number[][] = Array.from({ length: rows + 1 }, () => new Array<number>(columns + 1).fill(0))
  for (let i = rows - 1; i >= 0; i -= 1) {
    for (let j = columns - 1; j >= 0; j -= 1) {
      lengths[i][j] =
        before[i] === after[j] ? lengths[i + 1][j + 1] + 1 : Math.max(lengths[i + 1][j], lengths[i][j + 1])
    }
  }
  const keptBefore = new Array<boolean>(rows).fill(false)
  const keptAfter = new Array<boolean>(columns).fill(false)
  let i = 0
  let j = 0
  while (i < rows && j < columns) {
    if (before[i] === after[j]) {
      keptBefore[i] = true
      keptAfter[j] = true
      i += 1
      j += 1
    } else if (lengths[i + 1][j] >= lengths[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return [keptBefore, keptAfter]
}

/**
 * Align two values and mark every run as shared, gone, or new.
 *
 * The two sides are returned separately rather than as one unified stream,
 * because the display draws them as two chips side by side — the old value
 * washed red with its lost runs filled, the new value washed green with its
 * gained runs filled. A unified stream would force the display to re-split it.
 */
export function wordDiff(before: string, after: string): WordDiff {
  if (before === after) {
    return {
      before: before === "" ? [] : [{ text: before, kind: "same" }],
      after: after === "" ? [] : [{ text: after, kind: "same" }],
      changed: false,
    }
  }
  const beforeTokens = tokenizeFieldValue(before)
  const afterTokens = tokenizeFieldValue(after)
  // A rewrite is drawn as a rewrite. Aligning eighty scattered tokens
  // produces a mark per token, which reads as damage rather than as a change.
  if (beforeTokens.length > WORD_DIFF_TOKEN_LIMIT || afterTokens.length > WORD_DIFF_TOKEN_LIMIT) {
    return {
      before: before === "" ? [] : [{ text: before, kind: "removed" }],
      after: after === "" ? [] : [{ text: after, kind: "added" }],
      changed: true,
    }
  }
  const [keptBefore, keptAfter] = commonSubsequence(beforeTokens, afterTokens)
  return {
    before: coalesce(
      beforeTokens.map((text, index) => ({
        text,
        kind: keptBefore[index] ? "same" : "removed",
      })),
    ),
    after: coalesce(
      afterTokens.map((text, index) => ({
        text,
        kind: keptAfter[index] ? "same" : "added",
      })),
    ),
    changed: true,
  }
}

/** Stands in for the shared runs a compact former value leaves out. */
export const WORD_DIFF_ELISION = "…"

/**
 * The former value with its shared runs elided.
 *
 * A row is one line wide and a pair needs roughly twice the room a single value
 * does, so on a real board the title, the description and the port name all
 * overflowed — measured, three per capture. The fix is not a smaller font: it is
 * that half of what the pair was drawing is redundant. Every run the two values
 * SHARE is already legible in the current value an inch to the right, so the
 * former value only has to carry what it lost.
 *
 * `run_inference → run_predict` becomes `…inference → run_predict`: shorter than
 * the full pair, and the ink lands exactly on the run that changed rather than
 * on six characters that did not. The complete former value stays in the row's
 * tooltip, so nothing is unrecoverable.
 *
 * A shared run is only worth eliding when the ellipsis is actually shorter than
 * it, and a purely additive change returns nothing at all — there is no former
 * value worth a chip when nothing was taken away.
 */
export function compactFormerValue(tokens: readonly DiffToken[]): DiffToken[] {
  if (!tokens.some((token) => token.kind === "removed")) return []
  const compact: DiffToken[] = []
  for (const token of tokens) {
    if (token.kind !== "same") {
      compact.push(token)
      continue
    }
    if (token.text.length <= WORD_DIFF_ELISION.length) {
      compact.push(token)
      continue
    }
    const last = compact[compact.length - 1]
    // Never two ellipses in a row: `…a…` and `……` say the same thing and one
    // of them looks like a rendering fault.
    if (last?.kind === "same" && last.text === WORD_DIFF_ELISION) continue
    compact.push({ text: WORD_DIFF_ELISION, kind: "same" })
  }
  return compact
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
